window.products.push({"id":824319,"name":"Gunk B232-12PK Liquid Boiler Seal - 32 oz, (Case of 12)","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/71-SG7j2ZyL._AC_SL1500_.jpg","description":"A non-metallic liquid that securely seals cracks and leaks in boilers and fittings. Liquid boiler seal forms a tough filling that expands and contracts with heat and resists pressure. Liquid boiler seal is highly recommended for use in new installations to seal leaky joints and sand holes that might appear after initial installation. For use in either hot water or steam boilers.","images":["https://m.media-amazon.com/images/I/71-SG7j2ZyL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Gunk","source_asin":"B00BGSDWOQ","category_path":"Home & Kitchen"},"sku":"BM-824319","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00BGSDWOQ","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B00BGSDWOQ","price_pending":true,"merchant_ready":false});
